   159	export function computeShovelKinematics(
   160	  timeSec: number,
   161	  phaseOffset: number,
   162	  halted: boolean
   163	): ShovelPose {
   164	  if (halted) {
   165	    return {
   166	      swingAngle: -0.25,
   167	      boomPitch: 0,
   168	      stickExtension: -0.8,
   169	      bucketCurl: -0.35,
   170	    };
   171	  }
   172	
   173	  const cycle = (((timeSec * 0.45 + phaseOffset) % 1) + 1) % 1;
   174	  let swingAngle = 0;
   175	  let stickExtension = 0;
   176	  let bucketCurl = 0;
   177	  const boomPitch = Math.sin(cycle * Math.PI * 2) * 0.012;
   178	
   179	  if (cycle < 0.32) {
   180	    const u = cycle / 0.32;
   181	    const smooth = u * u * (3 - 2 * u);
   182	    swingAngle = 0;
   183	    stickExtension = -0.6 + smooth * 1.4;
   184	    bucketCurl = -0.2 + smooth * 0.55;
   185	  } else if (cycle < 0.58) {
   186	    const u = (cycle - 0.32) / 0.26;
   187	    const smooth = u * u * (3 - 2 * u);
   188	    swingAngle = smooth * 1.05;
   189	    stickExtension = 0.8 + Math.sin(u * Math.PI) * 0.25;
   190	    bucketCurl = 0.35;
   191	  } else if (cycle < 0.72) {
   192	    const u = (cycle - 0.58) / 0.14;
   193	    swingAngle = 1.05;
   194	    stickExtension = 0.8 - u * 0.3;
   195	    bucketCurl = 0.35 - Math.sin(u * Math.PI) * 0.85;
   196	  } else {
   197	    const u = (cycle - 0.72) / 0.28;
   198	    const smooth = u * u * (3 - 2 * u);
   199	    swingAngle = 1.05 * (1 - smooth);
   200	    stickExtension = 0.5 * (1 - smooth) - 0.6 * smooth;
   201	    bucketCurl = 0.35 * (1 - smooth) - 0.2 * smooth;
   202	  }
   203	
   204	  return {
   205	    swingAngle,
   206	    boomPitch,
   207	    stickExtension,
   208	    bucketCurl,
   209	  };
   210	}
